from functools import lru_cache

calls = 0

@lru_cache(maxsize=None)
def fib(n):
    global calls
    calls += 1                      # counts real executions, not cache hits
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print("fib(30) =", fib(30), "real calls:", calls)
print("cache_info:", fib.cache_info())

# pitfall: f(1) and f(a=1) are separate cache entries
@lru_cache(maxsize=None)
def f(a):
    return a * 2
f(1); f(a=1)
print("f cache entries:", f.cache_info().currsize)

# pitfall: arguments must be hashable
try:
    f([1, 2])
except TypeError as e:
    print("TypeError:", e)

# bounded cache evicts least recently used
@lru_cache(maxsize=2)
def g(x):
    return x
g(1); g(2); g(1); g(3)              # 2 is evicted
print("g info:", g.cache_info())

import sys

# a chain of 5000 nodes: left-skewed tree
class T:
    def __init__(self, v, left=None):
        self.v, self.left, self.right = v, left, None

root = None
for i in range(5000):
    root = T(i, root)

def depth_rec(n):
    return 0 if n is None else 1 + max(depth_rec(n.left), depth_rec(n.right))

try:
    print(depth_rec(root))
except RecursionError:
    print("recursive version: RecursionError (limit", sys.getrecursionlimit(), ")")

# iterative with an explicit stack: no recursion limit
def depth_iter(root):
    best, stack = 0, [(root, 1)]
    while stack:
        n, d = stack.pop()
        if n is None:
            continue
        best = max(best, d)
        stack.append((n.left, d + 1))
        stack.append((n.right, d + 1))
    return best

print("iterative depth:", depth_iter(root))
